from pathlib import Path
p=Path('/mnt/data/finmate_v343_work/app.js')
s=p.read_text()
# Quick actions
old='<div class="panel"><h3>Quick actions</h3><div class="list"><div class="row"><span>Bank / cash</span><button class="btn" data-action="add-bank">Add</button></div><div class="row"><span>Recurring entry</span><button class="btn" data-action="add-recurring">Add</button></div><div class="row"><span>Save latest encrypted data to Drive</span><button class="btn" data-action="drive-upload">↑ Upload</button></div></div></div>'
new='<div class="panel"><h3>Quick actions</h3><div class="list"><div class="row"><span>Add an expense</span><button class="btn" data-action="add-expense">＋ Expense</button></div><div class="row"><span>Add income</span><button class="btn" data-action="add-income">＋ Income</button></div><div class="row"><span>Upload encrypted vault to Drive</span><button class="btn" data-action="drive-upload">↑ Upload</button></div><div class="row"><span>Retrieve encrypted vault from Drive</span><button class="btn" data-action="drive-download">↓ Retrieve</button></div></div></div>'
