# Transaction dim class
old='<td class="transaction-amount"><strong>${this.money(t.amount)}</strong><small>${this.esc(t.date||\'\')}</small></td>'
new='<td class="transaction-amount ${this.transactionType(t.type)===\'expense\'&&t.countAsExpense===false?\'transaction-amount-not-counted\':\'\'}"><strong>${this.money(t.amount)}</strong>${this.transactionType(t.type)===\'expense\'&&t.countAsExpense===false?\'<small class="not-counted-label">Not counted as expense</small>\':\'\'}<small>${this.esc(t.date||\'\')}</small></td>'
