s=s.replace(old,new,1)
# Add tag field to gold form after jeweller field
old='<div class="field"><label>Jeweller (optional)</label><input id="g_jeweller" value="${this.esc(item?.jeweller||\'\')}"></div><div class="field"><label>Include in my investment?</label>'
new='<div class="field"><label>Jeweller (optional)</label><input id="g_jeweller" value="${this.esc(item?.jeweller||\'\')}"></div><div class="field"><label>Tag (optional)</label><input id="g_tag" value="${this.esc(item?.tag||\'\')}" placeholder="e.g. Mom’s jewellery, Wife’s jewellery"></div><div class="field"><label>Include in my investment?</label>'
