new="jeweller:document.getElementById('g_jeweller').value,tag:document.getElementById('g_tag').value.trim(),includeInInvestment:document.getElementById('g_include').value==='yes'"
assert old in s
s=s.replace(old,new,1)
# Gold analytics by tag: add grouping object and accumulation
old="const all=this.state.goldJewelry||[],items=scope==='mine'?all.filter(x=>x.includeInInvestment!==false):scope==='other'?all.filter(x=>x.includeInInvestment===false):all,byType={},byPurity={},byTypeValue={},byPurityValue={};items.forEach(x=>{const type=x.type||'Other',purity=x.purity||'Unknown',grams=Number(x.metalWeight??x.weight??0),value=Number(x.currentValue||0);byType[type]=(byType[type]||0)+grams;byPurity[purity]=(byPurity[purity]||0)+grams;byTypeValue[type]=(byTypeValue[type]||0)+value;byPurityValue[purity]=(byPurityValue[purity]||0)+value});"
new="const all=this.state.goldJewelry||[],items=scope==='mine'?all.filter(x=>x.includeInInvestment!==false):scope==='other'?all.filter(x=>x.includeInInvestment===false):all,byType={},byPurity={},byTypeValue={},byPurityValue={},byTag={},byTagValue={};items.forEach(x=>{const type=x.type||'Other',purity=x.purity||'Unknown',tag=String(x.tag||'').trim()||'Untagged',grams=Number(x.metalWeight??x.weight??0),value=Number(x.currentValue||0);byType[type]=(byType[type]||0)+grams;byPurity[purity]=(byPurity[purity]||0)+grams;byTypeValue[type]=(byTypeValue[type]||0)+value;byPurityValue[purity]=(byPurityValue[purity]||0)+value;byTag[tag]=(byTag[tag]||0)+grams;byTagValue[tag]=(byTagValue[tag]||0)+value});"
assert old in s
s=s.replace(old,new,1)
old="<div><div class=\"label\">Weight by purity</div>${Object.entries(byPurity).map(([k,v])=>`<div class=\"row\"><span>${this.esc(k)}</span><b>${v.toFixed(2)}g · ${this.money(byPurityValue[k]||0)}</b></div>`).join('')||'<div class=\"empty\">No data.</div>'}</div></div>`},"
new="<div><div class=\"label\">Weight by purity</div>${Object.entries(byPurity).map(([k,v])=>`<div class=\"row\"><span>${this.esc(k)}</span><b>${v.toFixed(2)}g · ${this.money(byPurityValue[k]||0)}</b></div>`).join('')||'<div class=\"empty\">No data.</div>'}</div><div><div class=\"label\">Weight by tag</div>${Object.entries(byTag).sort((a,b)=>a[0]==='Untagged'?-1:b[0]==='Untagged'?1:a[0].localeCompare(b[0])).map(([k,v])=>`<div class=\"row\"><span>${this.esc(k)}</span><b>${v.toFixed(2)}g · ${this.money(byTagValue[k]||0)}</b></div>`).join('')||'<div class=\"empty\">No data.</div>'}</div></div>`},"
assert old in s
s=s.replace(old,new,1)
# Replace goldJewelrySection method line
start=s.index(' goldJewelrySection(items,title,key,sort){')
end=s.index('\n goldAnalytics(',start)
newmethod=''' goldJewelrySection(items,title,key,sort){const sectionGrams=items.reduce((n,x)=>n+Number(x.metalWeight??x.weight??0),0),sectionInvestment=items.reduce((n,x)=>n+Number(x.purchasePrice||0),0),sectionCurrent=items.reduce((n,x)=>n+Number(x.currentValue||0),0);const sorted=[...items].sort((a,b)=>{const da=String(a.purchaseDate||''),db=String(b.purchaseDate||'');if(!da&&!db)return String(a.name||'').localeCompare(String(b.name||''));if(!da)return 1;if(!db)return -1;return sort==='oldest'?da.localeCompare(db):db.localeCompare(da)});const renderCards=arr=>arr.map(x=>`<div class="gold-item gold-item-clickable" data-action="view-gold" data-id="${x.id}" role="button" tabindex="0"><button type="button" class="gold-photo" data-action="view-gold-photo" data-id="${x.id}" aria-label="Enlarge jewellery photo">${x.photo?.data?`<img src="${x.photo.data}" alt="">`:'◇'}</button><div class="gold-info"><b>${this.esc(x.name||'Unnamed jewellery')}</b><small>${this.esc(x.purchaseDate||'No purchase date')} · ${this.esc(x.purity||'')} · ${Number(x.metalWeight??x.weight??0).toFixed(2)}g metal · ${this.esc(x.type||'')}</small><strong>${this.money(x.purchasePrice||0)}</strong><span class="${Number(x.currentValue||0)-Number(x.purchasePrice||0)>=0?'positive':'negative'}">${this.money(Number(x.currentValue||0)-Number(x.purchasePrice||0))} (${Number(x.purchasePrice||0)?((Number(x.currentValue||0)-Number(x.purchasePrice||0))/Number(x.purchasePrice||0)*100).toFixed(2):'0.00'}%)</span><div class="gold-inline-media">${x.bill?.data?`<button class="btn small" data-action="view-gold-bill" data-id="${x.id}">${x.bill.type?.includes('pdf')||/\\.pdf$/i.test(x.bill.name||'')?'Open invoice PDF':'View invoice'}</button>`:'<span class="note">No invoice</span>'}</div></div><div class="gold-item-actions"><span class="pill">${x.includeInInvestment===false?'Other jewellery':'Included in investment'}</span><button class="btn small" data-action="edit-gold" data-id="${x.id}">Edit</button><button class="btn small danger" data-action="delete-gold" data-id="${x.id}">Delete</button></div></div>`).join('');const untagged=sorted.filter(x=>!String(x.tag||'').trim()),tags=[...new Set(sorted.filter(x=>String(x.tag||'').trim()).map(x=>String(x.tag).trim()))].sort((a,b)=>a.localeCompare(b));const taggedGroups=tags.map((tag,i)=>{const group=sorted.filter(x=>String(x.tag||'').trim()===tag),grams=group.reduce((n,x)=>n+Number(x.metalWeight??x.weight??0),0),invest=group.reduce((n,x)=>n+Number(x.purchasePrice||0),0),current=group.reduce((n,x)=>n+Number(x.currentValue||0),0),gkey=`${key}-tag-${i}`;return `<details class="panel gold-tag-dropdown" data-persist-key="${gkey}"${this.disclosureAttr(gkey)}><summary><b>${this.esc(tag)}</b><span class="note">${group.length} item${group.length===1?'':'s'} · ${grams.toFixed(2)} g · Invested ${this.money(invest)} · Current ${this.money(current)}</span></summary><div class="gold-list">${renderCards(group)}</div></details>`}).join('');return `<details class="panel gold-section-dropdown" data-persist-key="${key}"${this.disclosureAttr(key)}><summary><b>${title}</b><span class="note">${items.length} item${items.length===1?'':'s'} · ${sectionGrams.toFixed(2)} g · Invested ${this.money(sectionInvestment)} · Current ${this.money(sectionCurrent)}</span></summary>${untagged.length?`<div class="gold-list">${renderCards(untagged)}</div>`:''}${taggedGroups}${!sorted.length?'<div class="empty">No entries in this section yet.</div>':''}</details>`},'''
s=s[:start]+newmethod+s[end:]
# CSS dim class
css=Path('/mnt/data/finmate_v343_work/app.css')
c=css.read_text()
c+='\n/* Visually de-emphasize expenses excluded from expense totals. */\n.transaction-amount-not-counted strong{opacity:.48;color:var(--muted,#9aa4b2);font-weight:500}.transaction-amount-not-counted .not-counted-label{display:block;color:var(--muted,#9aa4b2);font-size:.68rem;opacity:.9}\n.gold-tag-dropdown{margin:.5rem 0 0 1rem}\n'
css.write_text(c)
p.write_text(s)
